import React, { useState, useEffect, useContext, useCallback } from 'react';
import { DollarSign, Download, FileText } from 'lucide-react';
import { getSalaries, downloadSalarySlip } from '../../services/salaryService';
import Badge from '../../components/common/Badge';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { NotificationContext } from '../../context/NotificationContext';

const MySalaryPage = () => {
  const { addToast } = useContext(NotificationContext);
  const [salaries, setSalaries] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchSalaries = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getSalaries({ limit: 24 });
      setSalaries(res.data);
    } catch (err) {
      addToast('Failed to fetch salary records', 'danger');
    } finally {
      setLoading(false);
    }
  }, [addToast]);

  useEffect(() => {
    fetchSalaries();
  }, [fetchSalaries]);

  const handleDownloadPDF = async (id, salaryId) => {
    try {
      const res = await downloadSalarySlip(id);
      const url = window.URL.createObjectURL(new Blob([res.data], { type: 'application/pdf' }));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `SalarySlip_${salaryId}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      addToast('Salary slip PDF downloaded successfully!', 'success');
    } catch (err) {
      addToast('Failed to download salary slip PDF', 'danger');
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">My Earnings & Salary Statements</h1>
          <p className="page-subtitle">View monthly salary breakdowns, task payouts, and download official PDF salary slips</p>
        </div>
      </div>

      {loading ? (
        <LoadingSpinner />
      ) : (
        <div className="table-container">
          <table className="data-table">
            <thead>
              <tr>
                <th>Slip ID</th>
                <th>Pay Period</th>
                <th>Salary Model</th>
                <th>Base Fixed</th>
                <th>Task Incentive</th>
                <th>Bonus</th>
                <th>Penalty</th>
                <th>Total Net Payout</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {salaries.length === 0 ? (
                <tr>
                  <td colSpan="10" style={{ textAlign: 'center', padding: '30px', color: 'var(--text-muted)' }}>
                    No salary statements generated yet.
                  </td>
                </tr>
              ) : (
                salaries.map((s) => (
                  <tr key={s._id}>
                    <td>
                      <strong style={{ color: 'var(--primary)' }}>{s.salaryId}</strong>
                    </td>
                    <td>
                      <strong>
                        {s.month}/{s.year}
                      </strong>
                    </td>
                    <td>
                      <Badge text={s.salaryType} />
                    </td>
                    <td>${s.fixedSalary || 0}</td>
                    <td>${s.taskIncentive || 0}</td>
                    <td style={{ color: 'var(--success)' }}>+${s.bonus || 0}</td>
                    <td style={{ color: 'var(--danger)' }}>-${s.penalty || 0}</td>
                    <td>
                      <strong style={{ fontSize: '1.05rem', color: 'var(--success)' }}>
                        ${(s.totalEarnings || 0).toFixed(2)}
                      </strong>
                    </td>
                    <td>
                      <Badge text={s.status} />
                    </td>
                    <td>
                      <button
                        className="btn btn-secondary btn-sm"
                        onClick={() => handleDownloadPDF(s._id, s.salaryId)}
                      >
                        <Download size={14} /> PDF Slip
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default MySalaryPage;
